/// Theme-aware colors for notifications (success / error / warning / info),
/// each with a background and a matching `on` content color.
///
/// Registered in [ThemeData.extensions] by [M3Theme]; read it via
/// `BuildContext.notifyColorScheme` (or `notifyConfiguration` for a
/// type-to-`(bg, onBg)` pair). Not part of [ColorScheme] because Material has
/// no semantic role for these states.
@immutable
class NotifyColorExtension extends ThemeExtension<NotifyColorExtension> {
  const NotifyColorExtension({
    required this.success,
    required this.onSuccess,
    required this.error,
    required this.onError,
    required this.warning,
    required this.onWarning,
    required this.info,
    required this.onInfo,
  });

  final Color success;
  final Color onSuccess;

  final Color error;
  final Color onError;

  final Color warning;
  final Color onWarning;

  final Color info;
  final Color onInfo;

  static const light = NotifyColorExtension(
    success: Color(0xFFE8F5E9),
    onSuccess: Color(0xFF2E7D32),
    error: Color(0xFFFFEBEE),
    onError: Color(0xFFC62828),
    warning: Color(0xFFFFF3E0),
    onWarning: Color(0xFFEF6C00),
    info: Color(0xFFE1F5FE),
    onInfo: Color(0xFF0277BD),
  );

  static const dark = NotifyColorExtension(
    success: Color(0xFF1B5E20),
    onSuccess: Color(0xFFA5D6A7),
    error: Color(0xFF8C1D18),
    onError: Color(0xFFFFB4AB),
    warning: Color(0xFF5D3A00),
    onWarning: Color(0xFFFFB877),
    info: Color(0xFF01415C),
    onInfo: Color(0xFF81D4FA),
  );

  @override
  ThemeExtension<NotifyColorExtension> copyWith({
    Color? success,
    Color? onSuccess,
    Color? error,
    Color? onError,
    Color? warning,
    Color? onWarning,
    Color? info,
    Color? onInfo,
  }) => NotifyColorExtension(
    success: success ?? this.success,
    onSuccess: onSuccess ?? this.onSuccess,
    error: error ?? this.error,
    onError: onError ?? this.onError,
    warning: warning ?? this.warning,
    onWarning: onWarning ?? this.onWarning,
    info: info ?? this.info,
    onInfo: onInfo ?? this.onInfo,
  );

  @override
  NotifyColorExtension lerp(
    covariant ThemeExtension<NotifyColorExtension>? other,
    double t,
  ) {
    if (other is! NotifyColorExtension) return this;
    return NotifyColorExtension(
      success: Color.lerp(success, other.success, t)!,
      onSuccess: Color.lerp(onSuccess, other.onSuccess, t)!,
      error: Color.lerp(error, other.error, t)!,
      onError: Color.lerp(onError, other.onError, t)!,
      warning: Color.lerp(warning, other.warning, t)!,
      onWarning: Color.lerp(onWarning, other.onWarning, t)!,
      info: Color.lerp(info, other.info, t)!,
      onInfo: Color.lerp(onInfo, other.onInfo, t)!,
    );
  }
}

/// Calendar colors that have no Material [ColorScheme] role: the marks and
/// list items for system holidays (mùng 1, rằm and Tết festivals).
///
/// Anniversaries use [ColorScheme.primary]; holidays need a second, clearly
/// different hue. [ColorScheme.error] is not reused because it means
/// "something went wrong" to the user and to screen readers.
///
/// Registered in [ThemeData.extensions] by `M3Theme`; read it with
/// `context.calendarColors`. Values mirror the design-system tokens
/// `holiday-mark`, `holiday-container` and `on-holiday-container`.
@immutable
class CalendarColorExtension extends ThemeExtension<CalendarColorExtension> {
  /// Creates the calendar colors for one brightness.
  const CalendarColorExtension({
    required this.holidayMark,
    required this.holidayContainer,
    required this.onHolidayContainer,
  });

  /// The extension of the current theme; falls back to the built-in set
  /// for the theme's brightness when a theme does not register it.
  static CalendarColorExtension of(BuildContext context) {
    final theme = Theme.of(context);
    return theme.extension<CalendarColorExtension>() ??
        (theme.brightness == Brightness.dark ? dark : light);
  }

  /// Dot under a holiday and the red lunar number on days 1 and 15.
  final Color holidayMark;

  /// Background of a holiday item in the calendar day list.
  final Color holidayContainer;

  /// Text and icons on [holidayContainer].
  final Color onHolidayContainer;

  /// Light themes (standard, medium and high contrast).
  static const light = CalendarColorExtension(
    holidayMark: Color(0xFFC62828),
    holidayContainer: Color(0xFFFFDAD6),
    onHolidayContainer: Color(0xFF410002),
  );

  /// Dark themes (standard, medium and high contrast).
  static const dark = CalendarColorExtension(
    holidayMark: Color(0xFFFFB4A9),
    holidayContainer: Color(0xFF5C1A16),
    onHolidayContainer: Color(0xFFFFDAD6),
  );

  @override
  CalendarColorExtension copyWith({
    Color? holidayMark,
    Color? holidayContainer,
    Color? onHolidayContainer,
  }) => CalendarColorExtension(
    holidayMark: holidayMark ?? this.holidayMark,
    holidayContainer: holidayContainer ?? this.holidayContainer,
    onHolidayContainer: onHolidayContainer ?? this.onHolidayContainer,
  );

  @override
  CalendarColorExtension lerp(
    covariant ThemeExtension<CalendarColorExtension>? other,
    double t,
  ) {
    if (other is! CalendarColorExtension) return this;
    return CalendarColorExtension(
      holidayMark: _lerp(holidayMark, other.holidayMark, t),
      holidayContainer: _lerp(holidayContainer, other.holidayContainer, t),
      onHolidayContainer: _lerp(
        onHolidayContainer,
        other.onHolidayContainer,
        t,
      ),
    );
  }

  // Color.lerp only returns null when both ends are null; ours never are.
  static Color _lerp(Color a, Color b, double t) => Color.lerp(a, b, t) ?? a;
}

/// Convenience extension that converts a [ColorScheme] into a full [ThemeData].
///
/// Used internally by [M3Theme] getters — not part of the public API.
extension _AppThemeExtension on ColorScheme {
  /// Builds a Material 3 [ThemeData] from this [ColorScheme].
  ///
  /// - Text colors are derived from [onSurface] so they adapt to dark/light.
  /// - [InkSparkle] is used as the splash factory for a modern ripple effect.
  ThemeData get theme => ThemeData(
    extensions: [
      brightness == .dark
          ? NotifyColorExtension.dark
          : NotifyColorExtension.light,
      brightness == .dark
          ? CalendarColorExtension.dark
          : CalendarColorExtension.light,
    ],
    useMaterial3: true,
    colorScheme: this,
    textTheme: textTheme.apply(bodyColor: onSurface, displayColor: onSurface),
    scaffoldBackgroundColor: surface,
    canvasColor: surface,
    splashFactory: InkSparkle.splashFactory,
    drawerTheme: const DrawerThemeData(
      width: AppDimensions.navigationDrawerWidth,
    ),
    // Design system TextField: outlined, extra-small corners, tinted fill.
    inputDecorationTheme: InputDecorationThemeData(
      filled: true,
      fillColor: surfaceContainerLow,
      border: const OutlineInputBorder(
        borderRadius: BorderRadius.all(
          Radius.circular(AppDimensions.cornerExtraSmall),
        ),
      ),
    ),
  );

  /// M3 type scale (Typography.material2021) with two bundled families:
  /// [AppConfig.kDisplayFont] for display, headline and title styles, and
  /// [AppConfig.kBodyFont] for body and label styles.
  TextTheme get textTheme {
    final base =
        (brightness == .dark
                ? Typography.material2021().white
                : Typography.material2021().black)
            .apply(fontFamily: AppConfig.kBodyFont);
    TextStyle? display(TextStyle? style) =>
        style?.copyWith(fontFamily: AppConfig.kDisplayFont);
    return base.copyWith(
      displayLarge: display(base.displayLarge),
      displayMedium: display(base.displayMedium),
      displaySmall: display(base.displaySmall),
      headlineLarge: display(base.headlineLarge),
      headlineMedium: display(base.headlineMedium),
      headlineSmall: display(base.headlineSmall),
      titleLarge: display(base.titleLarge),
      titleMedium: display(base.titleMedium),
      titleSmall: display(base.titleSmall),
    );
  }
}
